//   client provider field is refused before it; fails_when=the strip or override loop is dropped or runs before the client field is kept; why_new=no
//   existing config sets either field; seam=none; no_claim=OpenRouter honoring the pin (local stub upstream)
// Value: protects=a plain JSON 200 is billed exactly from its usage and counts as a model response;
//   fails_when=the non-stream branch skips mergeUsage or bills worst; why_new=runner.test.ts:254 covers a 500 with
//   no usage and asserts counts only; seam=none; no_claim=real provider JSON shapes (stub upstream)
// Value: protects=an unreachable upstream returns 529, releases the pending worst case and charges nothing;
//   fails_when=the catch keeps the pending entry, so the next request is refused or close charges worst;
//   why_new=no test points a route at a dead port; seam=none; no_claim=other network faults (closed local port only)
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { costMicros, emptyUsage, startProxy, type ProxyConfig } from "../runner/proxy.ts";

const dir = mkdtempSync(join(tmpdir(), "laneb-paths-"));
const price = { input: 5, output: 25, cache_write_5m: 6.25, cache_write_1h: 10, cache_read: 0.5 };
const usage = { input_tokens: 1200, output_tokens: 150, cache_creation_input_tokens: 300, cache_read_input_tokens: 5000 };

describe("proxy body rewrite, non-stream metering and dead upstream", () => {
  const received: any[] = [];
  let upstream: ReturnType<typeof Bun.serve>;
  let live: ReturnType<typeof startProxy>;
  let dead: ReturnType<typeof startProxy>;

  beforeAll(() => {
    upstream = Bun.serve({
      hostname: "127.0.0.1",
      port: 0,
      async fetch(req) {
        received.push(await req.json());
        return Response.json({ id: "msg_1", type: "message", role: "assistant", content: [{ type: "text", text: "ok" }], stop_reason: "end_turn", usage });
      },
    });
    const probe = Bun.serve({ hostname: "127.0.0.1", port: 0, fetch: () => new Response() });
    const deadPort = probe.port;
    probe.stop(true);
    const config = (port: number | undefined): ProxyConfig => ({
      routes: { stub: { base_url: `http://127.0.0.1:${port}`, key_env: "FAKE_KEY", auth: "bearer", count_tokens: "estimate" } },
      models: {
        pinned: { route: "stub", upstream_model: "deepseek/deepseek-v4.1-flash-1017", price_per_mtok: price, strip_fields: ["context_management"], body_overrides: { provider: { only: ["deepseek"], allow_fallbacks: false } } },
        plain: { route: "stub", upstream_model: "claude-opus-5-5", price_per_mtok: price },
      },
    });
    const base = { dataHost: "127.0.0.1", dataPort: 0, controlPort: 0, env: { FAKE_KEY: "fake" }, closeWaitMs: 300 };
    live = startProxy({ ...base, config: config(upstream.port), logPath: join(dir, "live.jsonl"), sessionsPath: join(dir, "live-sess.jsonl") });
    dead = startProxy({ ...base, config: config(deadPort), logPath: join(dir, "dead.jsonl"), sessionsPath: join(dir, "dead-sess.jsonl"), globalCapMicros: 50_000 });
  });

  afterAll(async () => {
    await live.stop();
    await dead.stop();
    upstream.stop(true);
    rmSync(dir, { recursive: true, force: true });
  });

  const control = (p: ReturnType<typeof startProxy>) => `http://127.0.0.1:${p.control.port}`;
  const open = async (p: ReturnType<typeof startProxy>, model: string, cap: number) =>
    (await (await fetch(control(p) + "/sessions", { method: "POST", body: JSON.stringify({ trial: "t", model, cap_usd: cap }) })).json()) as any;
  const message = (p: ReturnType<typeof startProxy>, token: string, extra: Record<string, unknown> = {}) =>
    fetch(`http://127.0.0.1:${p.data.port}/v1/messages`, { method: "POST", headers: { authorization: "Bearer " + token, "content-type": "application/json" }, body: JSON.stringify({ model: "m", max_tokens: 1000, messages: [{ role: "user", content: "hi" }], ...extra }) });
  const close = async (p: ReturnType<typeof startProxy>, id: string) => (await (await fetch(control(p) + `/sessions/${id}/close`, { method: "POST", body: "{}" })).json()) as any;

  test("strip_fields are removed and body_overrides pin the provider; a client provider field is refused", async () => {
    const s = await open(live, "pinned", 0.5);
    const before = received.length;
    const refused = await message(live, s.token, { provider: { only: ["other"] } });
    expect(refused.status).toBe(400);
    await refused.text();
    expect(received.length).toBe(before);
    const res = await message(live, s.token, { context_management: { edits: [] }, temperature: 0.2 });
    expect(res.status).toBe(200);
    await res.text();
    await close(live, s.id);
    const body = received.at(-1);
    expect(body.model).toBe("deepseek/deepseek-v4.1-flash-1017");
    expect(body.provider).toEqual({ only: ["deepseek"], allow_fallbacks: false });
    expect("context_management" in body).toBe(false);
    expect(body.temperature).toBe(0.2);
  });

  test("a plain JSON 200 is billed exactly from its usage", async () => {
    const s = await open(live, "plain", 0.5);
    const res = await message(live, s.token, { stream: false });
    expect(res.status).toBe(200);
    expect(((await res.json()) as any).stop_reason).toBe("end_turn");
    const closed = await close(live, s.id);
    expect(closed.spent_micros).toBe(costMicros({ ...emptyUsage(), ...usage }, price));
    expect(closed.ok_responses).toBe(1);
    expect(closed.usage).toEqual({ ...emptyUsage(), ...usage });
  });

  test("an unreachable upstream returns 529, releases the pending worst case and charges nothing", async () => {
    const s = await open(dead, "plain", 0.05);
    for (let i = 0; i < 2; i++) {
      const res = await message(dead, s.token);
      expect(res.status).toBe(529);
      expect(((await res.json()) as any).error.type).toBe("overloaded_error");
    }
    const closed = await close(dead, s.id);
    expect(closed.requests).toBe(2);
    expect(closed.refused_budget).toBe(0);
    expect(closed.ok_responses).toBe(0);
    expect(closed.spent_micros).toBe(0);
    const totals = (await (await fetch(control(dead) + "/totals")).json()) as any;
    expect(totals).toMatchObject({ global_spent_micros: 0, cap_stop: null });
  });
});
